export class TokenBucketRateLimiter {
  private capacity: number;
  private refillRatePerSec: number;
  private tokens: number;
  private lastRefillTimestamp: number;

  constructor(capacity: number, refillRatePerSec: number) {
    this.capacity = capacity;
    this.refillRatePerSec = refillRatePerSec;
    this.tokens = capacity;
    this.lastRefillTimestamp = Date.now();
  }

  public allowRequest(tokensRequested = 1): boolean {
    this.refill();

    if (this.tokens >= tokensRequested) {
      this.tokens -= tokensRequested;
      return true; // Request accepted
    }

    return false; // Rate limit exceeded (HTTP 429)
  }

  private refill(): void {
    const now = Date.now();
    const elapsedSec = (now - this.lastRefillTimestamp) / 1000;
    const tokensToAdd = elapsedSec * this.refillRatePerSec;

    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefillTimestamp = now;
  }
}

class DNode {
  key: number;
  val: number;
  prev: DNode | null = null;
  next: DNode | null = null;
  constructor(key = 0, val = 0) {
    this.key = key;
    this.val = val;
  }
}

export class LRUCache {
  private capacity: number;
  private map = new Map<number, DNode>();
  private head = new DNode();
  private tail = new DNode();

  constructor(capacity: number) {
    this.capacity = capacity;
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  get(key: number): number {
    const node = this.map.get(key);
    if (!node) return -1;
    this.moveToHead(node);
    return node.val;
  }

  put(key: number, val: number): void {
    let node = this.map.get(key);
    if (node) {
      node.val = val;
      this.moveToHead(node);
    } else {
      node = new DNode(key, val);
      this.map.set(key, node);
      this.addToHead(node);
      if (this.map.size > this.capacity) {
        const lru = this.tail.prev!;
        this.removeNode(lru);
        this.map.delete(lru.key);
      }
    }
  }

  private removeNode(node: DNode) {
    node.prev!.next = node.next;
    node.next!.prev = node.prev;
  }

  private addToHead(node: DNode) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next!.prev = node;
    this.head.next = node;
  }

  private moveToHead(node: DNode) {
    this.removeNode(node);
    this.addToHead(node);
  }
}

import React, { useState, useMemo, useCallback } from 'react';

interface ListItemProps {
  item: string;
  onDelete: (item: string) => void;
}

// React.memo skips re-rendering if props are referentially identical
const ListItem = React.memo(({ item, onDelete }: ListItemProps) => {
  return (
    <li className="flex justify-between py-1">
      <span>{item}</span>
      <button onClick={() => onDelete(item)}>Delete</button>
    </li>
  );
});

export function ItemList() {
  const [items, setItems] = useState<string[]>(['Rust', 'Go', 'TypeScript']);
  const [query, setQuery] = useState('');

  // Stable callback reference
  const handleDelete = useCallback((toDelete: string) => {
    setItems((prev) => prev.filter((i) => i !== toDelete));
  }, []);

  // Filtered list only recalculates when items or query changes
  const filtered = useMemo(() => {
    return items.filter((i) => i.toLowerCase().includes(query.toLowerCase()));
  }, [items, query]);

  return (
    <div>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <ul>
        {filtered.map((item) => (
          <ListItem key={item} item={item} onDelete={handleDelete} />
        ))}
      </ul>
    </div>
  );
}

// Node.js Server-Sent Events (SSE) Stream Handler
import { createServer } from 'http';

createServer((req, res) => {
  if (req.url === '/events') {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    });

    // Send ping every 2 seconds
    const interval = setInterval(() => {
      const payload = JSON.stringify({ time: new Date().toISOString() });
      res.write(`data: ${payload}\n\n`);
    }, 2000);

    req.on('close', () => clearInterval(interval));
  }
}).listen(4000);

