#include <vector>
#include <algorithm>
#include <iostream>

int knapsack01(int W, const std::vector<int>& weights, const std::vector<int>& values) {
    int n = weights.size();
    // 1D DP array initialized to 0
    std::vector<int> dp(W + 1, 0);

    for (int i = 0; i < n; ++i) {
        // Traverse capacity backwards to prevent using item multiple times
        for (int w = W; w >= weights[i]; --w) {
            dp[w] = std::max(dp[w], dp[w - weights[i]] + values[i]);
        }
    }

    return dp[W];
}

