    std::vector<int> weights = {10, 20, 30};
    int W = 50;
    std::cout << "Max Value: " << knapsack01(W, weights, values) << "\n"; // 220
    return 0;
}

// Pseudo-code demonstrating Quorum Consistency (W + R > N)
// N = Replicas, W = Write Quorum, R = Read Quorum

interface Node {
  id: string;
  write(key: string, value: any, timestamp: number): Promise<boolean>;
  read(key: string): Promise<{ value: any; timestamp: number }>;
}

export async function strongQuorumRead(
  nodes: Node[],
  key: string,
  R: number
) {
  // Query R nodes concurrently
  const responses = await Promise.all(
    nodes.slice(0, R).map((node) => node.read(key))
  );

  // Pick the record with highest timestamp (Last Write Wins)
  responses.sort((a, b) => b.timestamp - a.timestamp);
  return responses[0].value;
}
